-- Use a transparent product cutout in banners, preserving the original library image and product photos.
UPDATE highlights SET image='/images/calendrier-conte-avent-detoure.png',version=version+1 WHERE id='calendrier-conte-avent' AND deleted=0 AND image IN ('/images/calendrier-conte-avent-photo.jpg','/media/e0b76e07-f0b5-40a4-a3a9-1c0cb7626a7d');
--> statement-breakpoint
UPDATE highlights_state SET version=version+1 WHERE id=1 AND EXISTS(SELECT 1 FROM highlights WHERE id='calendrier-conte-avent' AND image='/images/calendrier-conte-avent-detoure.png');
--> statement-breakpoint
UPDATE puck_pages SET published=CASE WHEN published IS NULL THEN NULL ELSE replace(replace(published,'/images/calendrier-conte-avent-photo.jpg','/images/calendrier-conte-avent-detoure.png'),'/media/e0b76e07-f0b5-40a4-a3a9-1c0cb7626a7d','/images/calendrier-conte-avent-detoure.png') END,draft=CASE WHEN draft IS NULL THEN NULL ELSE replace(replace(draft,'/images/calendrier-conte-avent-photo.jpg','/images/calendrier-conte-avent-detoure.png'),'/media/e0b76e07-f0b5-40a4-a3a9-1c0cb7626a7d','/images/calendrier-conte-avent-detoure.png') END,version=version+1 WHERE path='/' AND (instr(coalesce(published,''),'calendrier-conte-avent-photo.jpg')>0 OR instr(coalesce(draft,''),'calendrier-conte-avent-photo.jpg')>0 OR instr(coalesce(published,''),'e0b76e07-f0b5-40a4-a3a9-1c0cb7626a7d')>0 OR instr(coalesce(draft,''),'e0b76e07-f0b5-40a4-a3a9-1c0cb7626a7d')>0);
